-- Verify: this file owns exactly 346 rows for ER. The assertion counts only
-- rows whose path is declared in this file, so a correct re-run still passes even when
-- other rows exist for ER.
do $$
declare cnt integer;
begin
  select count(*) into cnt
  from public.locations
  where country_code = 'ER'
    and path = any (array[
      'eritrea',
      'eritrea/anseba-region',
      'eritrea/anseba-region/adi-tekeliezan-subregion',
      'eritrea/anseba-region/adi-tekeliezan-subregion/adi-tekelezan',
