      'eritrea/anseba-region/adi-tekeliezan-subregion/adi-tekeliezan-centre',
      'eritrea/anseba-region/adi-tekeliezan-subregion/keren-asmara-road-area',
      'eritrea/anseba-region/asmat-subregion',
      'eritrea/anseba-region/asmat-subregion/anseba-rural-area',
